  have q := fun k => IsLocalization.AtPrime.equivQuotMaximalIdealPow p S k;
  (Ideal.Quotient.factorₐ R ⋯).comp ↑(q n).symm = (↑(q m).symm).comp (Ideal.Quotient.factorₐ R ⋯)

LinearStudy.ringEquiv_nilradical_annihilator_generator.{u_2, u_3} {A : Type u_2} {C : Type u_3} [CommRing A]
  [CommRing C] (e : A ≃+* C) (theta : A) (h : Submodule.annihilator (nilradical A) = Ideal.span {theta}) :
