LinearStudy.normalize_formal_normal_equations_firstOrder.{u_1, u_3, u_4} {K : Type u_1} [Field K] {α : Type u_3}
  {β : Type u_4} [Fintype α] [Fintype β] [DecidableEq α] [DecidableEq β] [Nonempty β] (G : β → MvPowerSeries (α ⊕ β) K)
  (h0 : ∀ (i : β), MvPowerSeries.constantCoeff (G i) = 0)
  (hT : ∀ (i : β) (j : α), MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inl j)) (G i)) = 0)
  (hJ : IsUnit (Matrix.det fun i j => MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inr j)) (G i)))) :
  have J := fun i j => MvPowerSeries.constantCoeff ((MvPowerSeries.pderiv (Sum.inr j)) (G i));
  have H := fun i => ∑ j, J⁻¹ i j • G j;
  (∀ (i : β), H i - MvPowerSeries.X (Sum.inr i) ∈ IsLocalRing.maximalIdeal (MvPowerSeries (α ⊕ β) K) ^ 2) ∧
    Ideal.span (Set.range H) = Ideal.span (Set.range G)

LinearStudy.formal_pullback_firstOrder_unit_division.{u_1, u_2, u_3} {K : Type u_1} {σ : Type u_2} {τ : Type u_3}
  [Field K] [Fintype σ] [DecidableEq σ] [Nonempty σ] (p : σ → MvPowerSeries τ K)
  (h0 : ∀ (i : σ), MvPowerSeries.constantCoeff (p i) = 0) (u : (MvPowerSeries τ K)ˣ) (F : MvPowerSeries σ K) (j : σ)
  (hF : F - MvPowerSeries.X j ∈ IsLocalRing.maximalIdeal (MvPowerSeries σ K) ^ 2) :
  let v := fun i => ↑u⁻¹ * p i;
  have hv := ⋯;
  (MvPowerSeries.substAlgHom ⋯) F - ↑u⁻¹ * p j ∈ Ideal.span (Set.range p) ^ 2

LinearStudy.formal_pullback_jacobian_unit_factor.{u_1, u_2, u_3, u_4} {K : Type u_1} {σ : Type u_2} {τ : Type u_3}
  [Field K] [Fintype σ] [DecidableEq σ] [Nonempty σ] {β : Type u_4} [Fintype β] [DecidableEq β]
  (p : σ → MvPowerSeries τ K) (h0 : ∀ (i : σ), MvPowerSeries.constantCoeff (p i) = 0) (u : (MvPowerSeries τ K)ˣ)
  (G : β → MvPowerSeries σ K) (targetNormal : β → σ) (sourceNormal : β → τ)
  (hG : ∀ (i : β), G i - MvPowerSeries.X (targetNormal i) ∈ IsLocalRing.maximalIdeal (MvPowerSeries σ K) ^ 2) :
  have I := Ideal.span (Set.range p);
  let v := fun i => ↑u⁻¹ * p i;
  have hv := ⋯;
  have H := fun i => (MvPowerSeries.substAlgHom ⋯) (G i);
  (Ideal.Quotient.mk I) (Matrix.det fun i j => (MvPowerSeries.pderiv (sourceNormal j)) (H i)) =
    (Ideal.Quotient.mk I) ↑u⁻¹ ^ Fintype.card β *
      (Ideal.Quotient.mk I) (Matrix.det fun i j => (MvPowerSeries.pderiv (sourceNormal j)) (p (targetNormal i)))

LinearStudy.polynomial_equation_ideal_homogeneous.{u_1, u_2, u_3} {K : Type u_1} {ι : Type u_2} [Field K] {κ : Type u_3}
  (P : κ → MvPolynomial ι K) (d : κ → ℕ) (hP : ∀ (i : κ), (P i).IsHomogeneous (d i)) :
  Ideal.IsHomogeneous (MvPolynomial.homogeneousSubmodule ι K) (Ideal.span (Set.range P))

LinearStudy.coordinateRatioFieldMap.{u_1, u_2} {K : Type u_1} {F : Type u_2} [Field K] [Field F] [Algebra K F] {n : ℕ}
  (x : Fin (n + 1) → F) (hx : x 0 ≠ 0) (φ : F →ₐ[K] F) (p : Fin (n + 1) → MvPolynomial (Fin (n + 1)) K) {q : ℕ}
  (hp : ∀ (i : Fin (n + 1)), (p i).IsHomogeneous q) (hφ : ∀ (i : Fin (n + 1)), φ (x i) = (MvPolynomial.aeval x) (p i)) :
  ↥(LinearStudy.coordinateRatioField x) →ₐ[K] ↥(LinearStudy.coordinateRatioField x)

LinearStudy.homogeneous_projective_chart_pullback_ideal.{u_1} {K : Type u_1} [Field K] {n : ℕ}
  (I : Ideal (MvPolynomial (Fin (n + 1)) K))
  (hI : Ideal.IsHomogeneous (MvPolynomial.homogeneousSubmodule (Fin (n + 1)) K) I)
  (F : Fin (n + 1) → MvPolynomial (Fin (n + 1)) K) :
  have D := LinearStudy.affineChartPolynomialMap;
  have p0 := D (F 0);
  have p := fun i => D (F i.succ);
  Ideal.map (LinearStudy.rationalPolynomialChartMap p0 p).toRingHom (Ideal.map D.toRingHom I) =
    Ideal.map ((algebraMap (MvPolynomial (Fin n) K) (Localization.Away p0)).comp D.toRingHom)
      (Ideal.map (MvPolynomial.aeval F).toRingHom I)

LinearStudy.coordinate_annihilator_eq_coefficientDeterminant.{u_1} {R : Type u_1} [CommRing R] {k : ℕ}
  (H x : Fin (k + 1) → R) (hH : RingTheory.Sequence.IsRegular R (List.ofFn H))
  (hx : RingTheory.Sequence.IsRegular R (List.ofFn x)) (M : Matrix (Fin (k + 1)) (Fin (k + 1)) R) (h : M.mulVec x = H) :
  Submodule.annihilator (Ideal.map (Ideal.Quotient.mk (Ideal.span (Set.range H))) (Ideal.span (Set.range x))) =
    Ideal.span {(Ideal.Quotient.mk (Ideal.span (Set.range H))) M.det}

LinearStudy.linearEquationSubspace.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) :
  Projectivization.Subspace ℂ (LinearStudy.CoordinateVector n)

LinearStudy.mem_linearEquationSubmodule.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) (v : LinearStudy.CoordinateVector n) :
  v ∈ LinearStudy.linearEquationSubmodule equations ↔ ∀ (i : ι), (equations i) v = 0

LinearStudy.mem_linearEquationSubspace.{u_1} {n : ℕ} {ι : Type u_1}
  (equations : ι → LinearStudy.CoordinateVector n →ₗ[ℂ] ℂ) (v : LinearStudy.CoordinateVector n) (hv : v ≠ 0) :
