LinearStudy.localizationQuotientEquiv.{u_1} {R : Type u_1} [CommRing R] (I : Ideal R) (p : Ideal (R ⧸ I)) [p.IsPrime] :
  let P := Ideal.comap (Ideal.Quotient.mk I) p;
  let A := Localization.AtPrime P;
  (A ⧸ Ideal.map (algebraMap R A) I) ≃ₐ[R ⧸ I] Localization.AtPrime p

LinearStudy.localFiberCompletionQuotientEquiv.{u_1} {R : Type u_1} [CommRing R] [IsNoetherianRing R] (I : Ideal R)
  [IsArtinianRing (R ⧸ I)] (p : Ideal (R ⧸ I)) [p.IsPrime] :
  let A := Localization.AtPrime (Ideal.comap (Ideal.Quotient.mk I) p);
  let C := AdicCompletion (IsLocalRing.maximalIdeal A) A;
  C ⧸ Ideal.map (algebraMap A C) (Ideal.map (algebraMap R A) I) ≃+* Localization.AtPrime p

LinearStudy.local_fiber_socle_generator_of_completed_ambient.{u_1} {R : Type u_1} [CommRing R] [IsNoetherianRing R]
  (I : Ideal R) [IsArtinianRing (R ⧸ I)] (p : Ideal (R ⧸ I)) [p.IsPrime] (theta : R)
  (h :
    let A := Localization.AtPrime (Ideal.comap (Ideal.Quotient.mk I) p);
    let C := AdicCompletion (IsLocalRing.maximalIdeal A) A;
    let Q := C ⧸ Ideal.map (algebraMap A C) (Ideal.map (algebraMap R A) I);
    Submodule.annihilator (nilradical Q) =
      Ideal.span
        {(Ideal.Quotient.mk (Ideal.map (algebraMap A C) (Ideal.map (algebraMap R A) I)))
            ((algebraMap A C) ((algebraMap R A) theta))}) :
  Submodule.annihilator (nilradical (Localization.AtPrime p)) =
    Ideal.span {(algebraMap (R ⧸ I) (Localization.AtPrime p)) ((Ideal.Quotient.mk I) theta)}

LinearStudy.localRingHom_equiv_comp.{u_1, u_2, u_3} {R : Type u_1} {C : Type u_2} {A : Type u_3} [CommRing R]
  [CommRing C] [CommRing A] (φ : R →+* C) (E : C ≃+* A) (P : Ideal A) [P.IsPrime] :
  let p := Ideal.comap E.toRingHom P;
  let q := Ideal.comap φ p;
  (Localization.localRingEquiv p P E ⋯).toRingHom.comp (Localization.localRingHom q p φ ⋯) =
    Localization.localRingHom q P (E.toRingHom.comp φ) ⋯

LinearStudy.localRingHom_formallyUnramified_of_equiv_comp.{u_1, u_2, u_3} {R : Type u_1} {C : Type u_2} {A : Type u_3}
  [CommRing R] [CommRing C] [CommRing A] (φ : R →+* C) (E : C ≃+* A) (P : Ideal A) [P.IsPrime]
  (h :
    let p := Ideal.comap E.toRingHom P;
    let q := Ideal.comap φ p;
    (Localization.localRingHom q P (E.toRingHom.comp φ) ⋯).FormallyUnramified) :
  let p := Ideal.comap E.toRingHom P;
  let q := Ideal.comap φ p;
  (Localization.localRingHom q p φ ⋯).FormallyUnramified

LinearStudy.nilpotentPowerSeriesEval_C.{u_1, u_2} {R : Type u_1} {S : Type u_2} [CommRing R] [CommRing S] {n : ℕ}
  (f : R →+* S) (a : Fin n → S) (ha : ∀ (i : Fin n), IsNilpotent (a i)) (b : R) :
  (LinearStudy.nilpotentPowerSeriesEval f a ha) (MvPowerSeries.C b) = f b

LinearStudy.nilpotentPowerSeriesEval_X.{u_1, u_2} {R : Type u_1} {S : Type u_2} [CommRing R] [CommRing S] {n : ℕ}
  (f : R →+* S) (a : Fin n → S) (ha : ∀ (i : Fin n), IsNilpotent (a i)) (i : Fin n) :
  (LinearStudy.nilpotentPowerSeriesEval f a ha) (MvPowerSeries.X i) = a i

LinearStudy.oneVariable_closedFiber_jacobian.{u_1} {K : Type u_1} [Field K] [CharZero K] (H : PowerSeries K)
  (hH : H ≠ 0) (h0 : PowerSeries.constantCoeff H = 0) :
  have I := Ideal.span {H};
  let A := PowerSeries K ⧸ I;
  have delta := (Ideal.Quotient.mk I) (PowerSeries.derivative H);
  IsArtinianRing A ∧ (nilradical A).IsMaximal ∧ Submodule.annihilator (nilradical A) = Ideal.span {delta} ∧ delta ≠ 0

LinearStudy.polynomial_origin_height.{u_1} {K : Type u_1} [Field K] (n : ℕ) :
  have m := RingHom.ker (MvPolynomial.aeval 0).toRingHom;
  m.height = ↑n

LinearStudy.annihilator_scalar_action_baseChange.{u_1, u_2, u_3} {B : Type u_1} {C : Type u_2} {A : Type u_3}
  [CommRing B] [CommRing C] [CommRing A] [Algebra B A] [Algebra C A] (q : A →ₐ[B] B) (q' : A →ₐ[C] C) (e : B ≃+* C)
  (hq' : RingHom.ker q'.toRingHom = nilradical A) (he : ∀ (a : A), q' a = e (q a)) {delta : A}
  (hd : LinearStudy.Annihilates (nilradical A) delta) (b : B) : b • delta = e b • delta

LinearStudy.polynomialQuotient_nondegenerate_diagonal.{u_3} {F : Type u_3} [Field F] {n : ℕ}
  (P : Fin (n + 1) → MvPolynomial (Fin (n + 1)) F)
  (hP : RingTheory.Sequence.IsRegular (MvPolynomial (Fin (n + 1)) F) (List.ofFn P))
  [Module.Finite F (MvPolynomial (Fin (n + 1)) F ⧸ Ideal.span (Set.range P))] :
  let Q := MvPolynomial (Fin (n + 1)) F ⧸ Ideal.span (Set.range P);
  have pi := Ideal.Quotient.mk (Ideal.span (Set.range P));
  ∃ d,
    LinearStudy.Annihilates (KaehlerDifferential.ideal F Q) d ∧
      ((Algebra.TensorProduct.lmul' F) d = Matrix.det fun i j => pi ((MvPolynomial.pderiv j) (P i))) ∧
        ∀ (q : Q →ₐ[F] F), (LinearStudy.pairingRightReduction q) d ≠ 0

LinearStudy.polynomialQuotient_normalized_trace.{u_3} {F : Type u_3} [Field F] [IsAlgClosed F] [Infinite F] {n : ℕ}
  (P : Fin (n + 1) → MvPolynomial (Fin (n + 1)) F)
  (hP : RingTheory.Sequence.IsRegular (MvPolynomial (Fin (n + 1)) F) (List.ofFn P))
  [Module.Finite F (MvPolynomial (Fin (n + 1)) F ⧸ Ideal.span (Set.range P))] :
  let Q := MvPolynomial (Fin (n + 1)) F ⧸ Ideal.span (Set.range P);
  have pi := Ideal.Quotient.mk (Ideal.span (Set.range P));
  ∃ p, ∀ (a : Q), p.functional (a * Matrix.det fun i j => pi ((MvPolynomial.pderiv j) (P i))) = (Algebra.trace F Q) a

LinearStudy.polynomial_centered_coordinateIdeal_eq_eval_kernel.{u_1, u_3} {K : Type u_1} [Field K] {ι : Type u_3}
  [Fintype ι] [DecidableEq ι] (a : ι → K) :
  Ideal.span (Set.range fun i => MvPolynomial.X i - MvPolynomial.C (a i)) = RingHom.ker (MvPolynomial.aeval a).toRingHom

LinearStudy.polynomial_quotient_coordinateIdeal_eq_kernel.{u_1, u_3} {K : Type u_1} [Field K] {ι : Type u_3} [Fintype ι]
  [DecidableEq ι] (P : ι → MvPolynomial ι K) (q : MvPolynomial ι K ⧸ Ideal.span (Set.range P) →ₐ[K] K) :
  have pi := Ideal.Quotient.mk (Ideal.span (Set.range P));
  have a := fun i => q (pi (MvPolynomial.X i));
